// Bundles the grounding corpus and the shared output filter into the edge
// function directory. Run after any content change, before deploying `ask`.
import { readFileSync, writeFileSync } from "node:fs";

const grounding = readFileSync("content/llm/grounding.md", "utf8");
writeFileSync(
  "supabase/functions/ask/grounding.ts",
  "// GENERATED by scripts/build-ask-function.mjs; do not edit.\nexport const GROUNDING = " +
    JSON.stringify(grounding) + ";\n",
);

const filter = readFileSync("lib/ask-filter.ts", "utf8")
  .replace('export const ASK_DISCLOSURE', 'const _ASK_DISCLOSURE');
writeFileSync(
  "supabase/functions/ask/filter.ts",
  "// GENERATED from lib/ask-filter.ts by scripts/build-ask-function.mjs; do not edit.\n" + filter,
);
console.log("ask function assets built");
